const body = $input.first().json.body || $input.first().json || {};
const text = String(body.message?.text || body.query || '').trim();
const chatId = String(body.message?.chat?.id || body.chat_id || '');
const prToken = $env.TELEGRAM_PR_BOT_TOKEN || '';
const groqKey = $env.GROQ_API_KEY || '';
const brand = $env.BRAND_NAME || 'Tradesejon';

async function sendPrReply(msg) {
  if (chatId && prToken) {
    await fetch(`https://api.telegram.org/bot${prToken}/sendMessage`, {
      method: 'POST', headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ chat_id: chatId, text: msg, parse_mode: 'HTML' })
    }).catch(() => null);
  }
}

const BRAND = $env.BRAND_NAME || "Tradesejon";
const MENTORS = $env.MENTORS_LIST || "Senior Lead Strategist, Mentor Alpha, Mentor Beta, Mentor Gamma, Mentor Delta";
const PLATFORMS = $env.SUPPORTED_PLATFORMS || "Webull, Interactive Brokers (IBKR), TradingView";
const FAQS = [
  { q: "مبتدئ في التداول / الفيديوهات", a: `في ${BRAND} بنبدأ معاك من الصفر بخطة تدريبية منظمة وتطبيق عملي لايف عشان تتقن استراتيجية الـ Hyper-Scalping خطوة بخطوة.` },
  { q: "ايه المتطلبات عشان ابدأ؟", a: "لابتوب أو كمبيوتر، إنترنت مستقر، والتفرغ لحضور الجلسات اللايف المباشرة." },
  { q: "رأس المال المطلوب للبدء؟", a: "تقدر تبدأ بمرونة من $100 إلى $500 مع إدارة صارمة لرأس المال (WIN BIG, win small, lose small)." },
  { q: "منصات وبرامج التداول المعتمدة؟", a: `ندعم رسمياً منصات: ${PLATFORMS}.` },
  { q: "أوقات الجلسات اليومية المباشرة؟", a: $env.LIVE_SESSION_SCHEDULE || "يومياً من الإثنين للجمعة الساعة 9:30 مساءً عبر Discord VIP و Zoom." },
  { q: "أسعار ورشة التداول الأوفلاين؟", a: `${$env.WORKSHOP_MEMBER_PRICE || '4,000'} جنيه ($74.39) للأعضاء، و ${$env.WORKSHOP_NONMEMBER_PRICE || '6,000'} جنيه ($111.59) لغير المشتركين.` },
  { q: "اشتراك مجتمع وسكانر الديسكورد؟", a: `$${$env.VIP_MONTHLY_USD || '45'} شهرياً عبر Whop شاملة قنوات الـ VIP وسكانر الصفقات اللحظي.` },
  { q: "جلسة المتابعة الخاصة 4 ساعات؟", a: `جلسة Online 1-on-1 لمدة 4 ساعات بقيمة $${$env.PRIVATE_SESSION_USD || '100'} شاملة مراجعة المحفظة والتطبيق المباشر.` },
  { q: "من هم الموجهين والمدربين؟", a: `فريق التوجيه المعتمد في ${BRAND}: ${MENTORS}.` },
  { q: "طريقة وأسلوب التداول؟", a: "استراتيجية الـ Hyper-Scalping بمبدأ WIN BIG, win small, lose small." },
  { q: "هل يوجد توصيات شراء وبيع مباشرة؟", a: "بنوفرلك تحليلات لايف ومناطق دخول احترافية وسكانر لحظي مع تدريبك على القرار المستقل." },
  { q: "كيفية تجديد الاشتراك أو الترقية؟", a: "عبر بوابة الدفع الرسمية Whop بشكل تلقائي بالكامل وبمرونة الإلغاء بأي وقت." },
  { q: "هل الديسكورد متصل بالتيليجرام؟", a: `نعم، منظومة ${BRAND} Omnichannel تربط الديسكورد والتيليجرام بشكل لحظي متزامن.` },
  { q: "ماذا أفعل لو واجهت مشكلة في الدفع؟", a: "تواصل مع بوت الدعم الفني أو افتح تذكرة في روم #pr-desk في الديسكورد." },
  { q: "هل متوفر شهادة بعد الورشة؟", a: `نعم، يحصل الخريج على شهادة إتمام البرنامج التدريبي المعتمد من ${BRAND}.` },
  { q: "هل التداول مناسب للموظفين؟", a: "نعم، جلساتنا المسائية الساعة 9:30 مساءً بتوقيت القاهرة تناسب جدول العمل اليومي." },
  { q: "كيف أحصل على رابط الجلسة المباشرة؟", a: "يرسل الرابط المشفر تلقائياً عبر البوت قبل بدء الجلسة بـ 15 دقيقة." }
];
for (const f of FAQS) {
  if (text.includes(f.q) || f.q.split(' ').filter(w => w.length > 3).filter(w => text.includes(w)).length >= 2) {
    await sendPrReply(f.a);
    return [{ json: { ok: true, faq_matched: true, reply: f.a } }];
  }
}

if (/(?:indicator|script|scanner|سكانر|مؤشر|توصية)/i.test(text)) {
  const guardMsg = `🔒 <b>${brand} PR Desk:</b>\nVIP Indicators and Scanners are available to active members.\nSubscribe via Whop: ${$env.WHOP_CHECKOUT_URL || 'Configure WHOP_CHECKOUT_URL'}`;
  await sendPrReply(guardMsg);
  return [{ json: { ok: true, guarded: true, reply: guardMsg } }];
}

let reply = `Welcome to ${brand} Public Relations Desk! Ask about membership pricing, live sessions, or workshops.`;
if (groqKey && text) {
  const r = await fetch('https://api.groq.com/openai/v1/chat/completions', {
    method: 'POST', headers: { 'Authorization': `Bearer ${groqKey}`, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: 'llama-3.3-70b-versatile',
      messages: [
        { role: 'system', content: `You are ${brand} PR Representative. Answer strictly based on configured pricing and platforms (${PLATFORMS}). Never invent unverified links.` },
        { role: 'user', content: text }
      ]
    })
  }).then(res => res.json()).catch(() => ({}));
  if (r.choices?.[0]?.message?.content) reply = r.choices[0].message.content;
}

await sendPrReply(reply);
return [{ json: { ok: true, reply } }];
